class OrderController {
  createOrder(req, res) {
    const user = Auth.verify(req.headers.token);
    if (!user) return res.status(401);
    const total = this.calculateTotal(req.body.items);
    const order = new Order(req.body);
    order.save();
    res.json({ id: order.id, total: total });
  }
}

class InvoiceService {
  createInvoice(data) {
    validate(data);
    const pdf = PdfFormatter.format(data);
    const id = Database.insert('invoices', { data, pdf });
    Email.send(data.email, pdf);
    Logger.info('invoice created', id);
    return id;
  }
}

